const PolylineFlowMaterialProperty = utilscesium.Material.PolylineFlowMaterialProperty;
let entity = viewer.entities.add({
  polyline: {
    positions: new Cesium.CallbackProperty(() => {
      let length = getlength([
        [120, 28],
        [120, 29],
        [121, 29],
      ]);
      return Cesium.Cartesian3.fromDegreesArray([120, 28, 120, 29, 121, 29]);
    }, false),
    material: new PolylineFlowMaterialProperty({
      image: "./images/spriteline.png",
      color: Cesium.Color.WHITE,
      duration: 3000,
      repeat: {
        x: 1,
        y: 1,
      },
    }),
    width: 1.7,
  },
});

viewer.zoomTo(entity);

function getlength(coors) {
  var coors2 = [];
  for (let i = 0; i < coors.length; i++) {
    coors2.push(
      viewer.scene.cartesianToCanvasCoordinates(
        Cesium.Cartesian3.fromDegrees(coors[i][0], coors[i][1])
      )
    );
  }
  let length = 0;
  for (let i = 1; i < coors2.length; i++) {
    if (!coors2[i] || !coors2[i - 1]) {
      return 0;
    }
    let len = Math.sqrt(
      (coors2[i].x - coors2[i - 1].x) ** 2 +
        (coors2[i].y - coors2[i - 1].y) ** 2
    );
    length += len;
  }

  return length;
}
